// Format pesan ringkasan transaksi & notifikasi tim internal
const item = $input.first().json.body || $input.first().json;

const formattedBudget = new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  maximumFractionDigits: 0
}).format(item.budget_estimate_idr || 0);

const notificationText = `🚀 *PROSPEK/ORDER BARU MASUK*\n` +
  `----------------------------\n` +
  `*ID:* ${item.tracking_id}\n` +
  `*Nama:* ${item.customer_name}\n` +
  `*WhatsApp:* ${item.customer_whatsapp}\n` +
  `*Layanan:* ${item.service_type}\n` +
  `*Estimasi Budget:* ${formattedBudget}\n` +
  `*Catatan:* ${item.notes}\n` +
  `*Waktu:* ${item.created_at}`;

return [
  {
    json: {
      ...item,
      formatted_budget: formattedBudget,
      telegram_or_wa_message: notificationText
    }
  }
];
